}

import type { Server } from "socket.io";

// A tiny module-level singleton that lets HTTP-triggered Actions
// (saveVersion, restoreVersion, shareDocument, revokePermission) broadcast
// real-time updates over the same Socket.IO server instance that Wasp's
// `webSocketFn` sets up. Both the WebSocket handler and the Actions run in
// the same Node.js process, so sharing the `io` instance this way works
// reliably.
let ioInstance: Server | null = null;

export function setIO(io: Server): void {
  ioInstance = io;
}

export function getIO(): Server | null {
  return ioInstance;
}

export function documentRoom(documentId: number | string): string {
  return `document:${documentId}`;
}

export type Role = "OWNER" | "EDIT" | "VIEW";

export interface VersionDTO {
  id: number;
  content: string;
  authorUsername: string;
  createdAt: Date;
}

export interface PermissionDTO {
  id: number;
  userId: number;
  username: string;
  role: string;
}

export interface DocumentListItem {
  id: number;
  title: string;
  updatedAt: Date;
  isOwner: boolean;
  role: Role;
  ownerUsername: string;
}

export interface DocumentDetails {
  id: number;
  title: string;
  content: string;
  isOwner: boolean;
  role: Role;
  canEdit: boolean;
  ownerUsername: string;
  versions: VersionDTO[];
  permissions: PermissionDTO[];
}

export interface PermissionLike {
  userId: number;
  role: string;
}

export interface DocumentLike {
  ownerId: number;
  permissions: PermissionLike[];
}

export interface AccessInfo {
  isOwner: boolean;
  permissionRole: "VIEW" | "EDIT" | null;
  canView: boolean;
  canEdit: boolean;
}

/**
 * Figures out whether a user can view/edit a document, based on document
 * ownership and any explicit `Permission` record for that user.
 */
export function computeAccess(doc: DocumentLike, userId: number): AccessInfo {
  const isOwner = doc.ownerId === userId;
  const permission = doc.permissions.find((p) => p.userId === userId);
  const permissionRole = permission ? (permission.role as "VIEW" | "EDIT") : null;
  const canView = isOwner || permission !== undefined;
  const canEdit = isOwner || permissionRole === "EDIT";

  return { isOwner, permissionRole, canView, canEdit };
}

import { HttpError } from "wasp/server";
import { type GetMyDocuments, type GetDocument } from "wasp/server/operations";

import { computeAccess } from "../access";
import type { DocumentDetails, DocumentListItem, Role } from "../shared/types";

export const getMyDocuments: GetMyDocuments<void, DocumentListItem[]> = async (
  _args,
  context,
) => {
  if (!context.user) {
    throw new HttpError(401);
  }
  const userId = context.user.id;

  const documents = await context.entities.Document.findMany({
    where: {
      OR: [{ ownerId: userId }, { permissions: { some: { userId } } }],
    },
    include: {
      owner: true,
      permissions: true,
    },
    orderBy: { updatedAt: "desc" },
  });

  return documents.map((doc) => {
    const access = computeAccess(doc, userId);
    const role: Role = access.isOwner ? "OWNER" : (access.permissionRole as Role);
    return {
      id: doc.id,
      title: doc.title,
      updatedAt: doc.updatedAt,
      isOwner: access.isOwner,
      role,
      ownerUsername: doc.owner.username,
    };
  });
};

export const getDocument: GetDocument<{ id: number }, DocumentDetails> = async (
  { id },
  context,
) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  const doc = await context.entities.Document.findUnique({
    where: { id },
    include: {
      owner: true,
      permissions: { include: { user: true } },
      versions: { include: { author: true }, orderBy: { id: "asc" } },
    },
  });

  if (!doc) {
    throw new HttpError(404, "Document not found");
  }

  const access = computeAccess(doc, context.user.id);
  if (!access.canView) {
    throw new HttpError(403, "Access denied");
  }

  const role: Role = access.isOwner ? "OWNER" : (access.permissionRole as Role);

  return {
    id: doc.id,
    title: doc.title,
    content: doc.content,
    isOwner: access.isOwner,
    role,
    canEdit: access.canEdit,
    ownerUsername: doc.owner.username,
    versions: doc.versions.map((v) => ({
      id: v.id,
      content: v.content,
      authorUsername: v.author.username,
      createdAt: v.createdAt,
    })),
    permissions: doc.permissions.map((p) => ({
      id: p.id,
      userId: p.userId,
      username: p.user.username,
      role: p.role,
    })),
  };
};

import { HttpError } from "wasp/server";
import {
  type CreateDocument,
  type SaveVersion,
  type RestoreVersion,
  type ShareDocument,
  type RevokePermission,
} from "wasp/server/operations";

import { computeAccess } from "../access";
import { documentRoom, getIO } from "../socketIO";
import type { PermissionDTO, VersionDTO } from "../shared/types";

export const createDocument: CreateDocument<{ title: string }, { id: number }> =
  async ({ title }, context) => {
    if (!context.user) {
      throw new HttpError(401);
    }
    const trimmedTitle = title?.trim();
    if (!trimmedTitle) {
      throw new HttpError(400, "Title is required");
    }

    const document = await context.entities.Document.create({
      data: {
        title: trimmedTitle,
        ownerId: context.user.id,
      },
    });

    return { id: document.id };
  };

export const saveVersion: SaveVersion<
  { documentId: number; content: string },
  { version: VersionDTO }
> = async ({ documentId, content }, context) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  const doc = await context.entities.Document.findUnique({
    where: { id: documentId },
    include: { permissions: true },
  });
  if (!doc) {
    throw new HttpError(404, "Document not found");
  }

  const access = computeAccess(doc, context.user.id);
  if (!access.canEdit) {
    throw new HttpError(403, "You don't have permission to edit this document");
  }

  const version = await context.entities.Version.create({
    data: {
      documentId,
      content,
      authorId: context.user.id,
    },
    include: { author: true },
  });

  await context.entities.Document.update({
    where: { id: documentId },
    data: { content },
  });

  const versionDTO: VersionDTO = {
    id: version.id,
    content: version.content,
    authorUsername: version.author.username,
    createdAt: version.createdAt,
  };

  getIO()
    ?.to(documentRoom(documentId))
    .emit("versionSaved", { documentId, version: versionDTO, content });

  return { version: versionDTO };
};

export const restoreVersion: RestoreVersion<
  { documentId: number; versionId: number },
  { content: string }
> = async ({ documentId, versionId }, context) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  const doc = await context.entities.Document.findUnique({
    where: { id: documentId },
    include: { permissions: true },
  });
  if (!doc) {
    throw new HttpError(404, "Document not found");
  }

  const access = computeAccess(doc, context.user.id);
  if (!access.canEdit) {
    throw new HttpError(403, "You don't have permission to edit this document");
  }

  const version = await context.entities.Version.findUnique({
    where: { id: versionId },
  });
  if (!version || version.documentId !== documentId) {
    throw new HttpError(404, "Version not found");
  }

  await context.entities.Document.update({
    where: { id: documentId },
    data: { content: version.content },
  });

  getIO()
    ?.to(documentRoom(documentId))
    .emit("documentRestored", {
      documentId,
      content: version.content,
      versionId: version.id,
    });

  return { content: version.content };
};

export const shareDocument: ShareDocument<
  { documentId: number; username: string; role: string },
  { permissions: PermissionDTO[] }
> = async ({ documentId, username, role }, context) => {
  if (!context.user) {
    throw new HttpError(401);
  }
  if (role !== "VIEW" && role !== "EDIT") {
    throw new HttpError(400, "Role must be VIEW or EDIT");
  }

  const doc = await context.entities.Document.findUnique({
    where: { id: documentId },
  });
  if (!doc) {
    throw new HttpError(404, "Document not found");
  }
  if (doc.ownerId !== context.user.id) {
    throw new HttpError(403, "Only the owner can share this document");
  }

  const trimmedUsername = username?.trim();
  if (!trimmedUsername) {
    throw new HttpError(400, "Username is required");
  }

  const targetUser = await context.entities.User.findUnique({
    where: { username: trimmedUsername },
  });
  if (!targetUser) {
    throw new HttpError(404, "User not found");
  }
  if (targetUser.id === context.user.id) {
    throw new HttpError(400, "You cannot share a document with yourself");
  }

  await context.entities.Permission.upsert({
    where: {
      documentId_userId: {
        documentId,
        userId: targetUser.id,
      },
    },
    update: { role },
    create: { documentId, userId: targetUser.id, role },
  });

  const permissions = await getPermissionDTOs(context, documentId);

  getIO()
    ?.to(documentRoom(documentId))
    .emit("permissionsChanged", { documentId, permissions });

  return { permissions };
};

export const revokePermission: RevokePermission<
  { documentId: number; permissionId: number },
  { permissions: PermissionDTO[] }
> = async ({ documentId, permissionId }, context) => {
  if (!context.user) {
    throw new HttpError(401);
  }

  const doc = await context.entities.Document.findUnique({
    where: { id: documentId },
  });
  if (!doc) {
    throw new HttpError(404, "Document not found");
  }
  if (doc.ownerId !== context.user.id) {
    throw new HttpError(403, "Only the owner can revoke access");
  }

  await context.entities.Permission.deleteMany({
    where: { id: permissionId, documentId },
  });

  const permissions = await getPermissionDTOs(context, documentId);

  getIO()
    ?.to(documentRoom(documentId))
    .emit("permissionsChanged", { documentId, permissions });

  return { permissions };
};

async function getPermissionDTOs(
  context: {
    entities: {
      Permission: {
        findMany: (args: unknown) => Promise<
          { id: number; userId: number; role: string; user: { username: string } }[]
        >;
      };
    };
  },
  documentId: number,
): Promise<PermissionDTO[]> {
  const permissions = await context.entities.Permission.findMany({
    where: { documentId },
    include: { user: true },
  });
  return permissions.map((p) => ({
    id: p.id,
    userId: p.userId,
    username: p.user.username,
    role: p.role,
  }));
}

